"""Goal 18 — the ``POST /search`` transcript search endpoint.

This module is the **HTTP transport layer only**. It turns a validated JSON
request into a call to Goal 17's read-only :class:`VideoChunkSearchService`
and maps the service's domain errors onto HTTP status codes.

Scope boundary (see ``progress.md``):

* Goal 18 (this module): the search endpoint, request contract, dependency
  wiring and error translation.
* Goal 19: natural-language ``query`` text -> validated embedding, generated by
  :class:`app.embeddings.query.QueryEmbeddingService` in the isolated worker.
  The precomputed ``query_vector`` input remains supported (Goal 18).
* Goal 20 / Goal 21: richer retrieval policies and the final public response
  schema. The minimal response envelope below exists only so the endpoint can
  return a useful, bounded payload.

No model is loaded in this process: the query embedder launches the optional
isolated interpreter as a subprocess only when ``query`` is supplied.

Nothing in this module writes to the database: there is no commit, flush,
rollback, or DDL. The injected session is owned and closed by ``get_db``.
"""
from __future__ import annotations

from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import (
    BaseModel,
    ConfigDict,
    Field,
    StrictFloat,
    StrictInt,
    StrictStr,
    model_validator,
)
from sqlalchemy.orm import Session

from app.db.session import get_db
from app.embeddings.contracts import DENSE_DIMENSION, EmbeddingError, InvalidEmbeddingInputError
from app.embeddings.query import QueryEmbeddingService
from app.repositories.video_chunks import DEFAULT_TOP_K
from app.services.video_chunks import SearchError, VideoChunkSearchService

router = APIRouter(tags=["search"])


class SearchRequest(BaseModel):
    """Strict JSON body for ``POST /search``.

    ``Strict*`` scalars prevent silent coercion (e.g. ``"10"`` -> ``10``,
    ``True`` -> ``1``). The vector is length-bounded at the HTTP boundary to
    avoid unbounded request bodies; dimension, finiteness and normalization
    are still validated by the Goal 17 service via the Goal 15 contract.
    """

    model_config = ConfigDict(extra="forbid")

    # Goal 19: `query` generates the vector through the isolated worker;
    # `query_vector` remains supported for precomputed vectors (Goal 18).
    query: StrictStr | None = None
    query_vector: Annotated[
        list[StrictFloat] | None, Field(max_length=DENSE_DIMENSION)
    ] = None
    top_k: StrictInt = DEFAULT_TOP_K
    video_id: UUID | None = None
    transcript_asset_id: UUID | None = None
    model_id: StrictStr | None = None

    @model_validator(mode="after")
    def _exactly_one_query_source(self) -> "SearchRequest":
        if (self.query is None) == (self.query_vector is None):
            raise ValueError("provide exactly one of query or query_vector")
        return self


class SearchHit(BaseModel):
    """One ranked chunk returned by the endpoint (no raw embedding)."""

    model_config = ConfigDict(from_attributes=True)

    id: UUID
    video_id: UUID
    transcript_asset_id: UUID
    content_right_id: UUID
    chunk_index: int
    text: str
    start_ms: int
    end_ms: int
    duration_ms: int
    timestamp_precision: str
    word_count: int
    boundary_reason: str
    source_segment_refs: list[str]
    overlap_sentence_indices: list[int]
    diagnostics: list[str]
    model_id: str
    distance: float
    score: float


class SearchResponse(BaseModel):
    """Minimal response envelope for the Goal 18 endpoint."""

    count: int
    results: list[SearchHit]


def get_search_service(
    session: Annotated[Session, Depends(get_db)],
) -> VideoChunkSearchService:
    """FastAPI dependency: build the Goal 17 service over a request session."""
    return VideoChunkSearchService(session)


def get_query_embedding_service() -> QueryEmbeddingService:
    """FastAPI dependency: build the Goal 19 query embedder (no model load)."""
    return QueryEmbeddingService()


@router.post(
    "/search",
    response_model=SearchResponse,
    status_code=status.HTTP_200_OK,
    summary="Search transcript chunks by cosine similarity",
)
def search(
    payload: SearchRequest,
    service: Annotated[VideoChunkSearchService, Depends(get_search_service)],
    embedder: Annotated[
        QueryEmbeddingService, Depends(get_query_embedding_service)
    ],
) -> SearchResponse:
    """Return the top-k chunks nearest the request's query vector.

    A natural-language ``query`` is embedded by the isolated Goal 19 worker;
    a precomputed ``query_vector`` is used directly. Domain and embedding
    validation failures are translated to credential-free HTTP errors.
    Unexpected failures propagate so FastAPI returns 500; they are never
    converted into a successful empty result.
    """
    if payload.query is not None:
        try:
            query_vector = embedder.embed(payload.query).values
        except InvalidEmbeddingInputError as exc:
            raise HTTPException(
                status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=str(exc)
            ) from exc
        except EmbeddingError as exc:
            # Model-load / inference / unavailable-worker failures are server-side.
            raise HTTPException(
                status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=str(exc)
            ) from exc
    else:
        if payload.query_vector is None:  # unreachable after request validation
            raise HTTPException(
                status_code=status.HTTP_422_UNPROCESSABLE_CONTENT,
                detail="query or query_vector is required",
            )
        query_vector = payload.query_vector

    try:
        results = service.search(
            query_vector,
            top_k=payload.top_k,
            video_id=payload.video_id,
            transcript_asset_id=payload.transcript_asset_id,
            model_id=payload.model_id,
        )
    except SearchError as exc:
        raise HTTPException(
            status_code=status.HTTP_422_UNPROCESSABLE_CONTENT, detail=str(exc)
        ) from exc

    return SearchResponse(
        count=len(results),
        results=[SearchHit.model_validate(result) for result in results],
    )


__all__ = [
    "SearchHit",
    "SearchRequest",
    "SearchResponse",
    "get_query_embedding_service",
    "get_search_service",
    "router",
]
